// Patches the load.js generated by container2wasm (Emscripten's file_packager) so downloading the data
// package doesn't take twice the memory: the original keeps every chunk and at the end copies them into a
// new buffer (two copies of ~660 MB at once); this allocates the buffer once, with the known size, and
// copies each chunk as it arrives. Idempotent; run it after every build.
//
//   node safari/patch-load.mjs [build/base/htdocs]
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const file = path.join(path.resolve(here, process.argv[2] || 'build/base/htdocs'), 'load.js');
let s = fs.readFileSync(file, 'utf8');
const MARK = '/* bolsillo: single buffer */';
if (s.includes(MARK)) { console.log(`already patched: ${file}`); process.exit(0); }

const replace = (from, to) => {
  if (!s.includes(from)) throw new Error(`can't find in ${file}:\n${from}`);
  s = s.replace(from, to);
};
replace('const chunks = [];', `${MARK} let packageData = new Uint8Array(packageSize);`);
replace(`                chunks.push(value);
                loaded += value.length;`, `                if (loaded + value.length > packageData.length) { // in case the announced size falls short
                  const bigger = new Uint8Array(Math.max(loaded + value.length, packageData.length * 1.25));
                  bigger.set(packageData.subarray(0, loaded));
                  packageData = bigger;
                }
                packageData.set(value, loaded);
                loaded += value.length;`);
replace(`                const packageData = new Uint8Array(chunks.map((c) => c.length).reduce((a, b) => a + b, 0));
                let offset = 0;
                for (const chunk of chunks) {
                  packageData.set(chunk, offset);
                  offset += chunk.length;
                }
                callback(packageData.buffer);`, `                callback(loaded === packageData.length ? packageData.buffer : packageData.slice(0, loaded).buffer);`);
fs.writeFileSync(file, s);
console.log(`patched: ${file}`);
